const { withAppBuildGradle } = require("expo/config-plugins");

// Android's default CMake 3.22.1 bundles ninja 1.10, which cannot create build
// directories deeper than Windows' 260-character limit. Autolinked codegen paths
// (for example @lodev09/react-native-true-sheet) exceed it, so the app module
// must use CMake 4.1.2, which bundles a long-path-aware ninja.
//
// `android/` is generated by prebuild, so the fix lives here instead of being
// hand-edited into app/build.gradle.
const CMAKE_VERSION = "4.1.2";

module.exports = function withLongPathCmake(config) {
  return withAppBuildGradle(config, (config) => {
    if (config.modResults.language !== "groovy") return config;
    const contents = config.modResults.contents;
    if (contents.includes(`version "${CMAKE_VERSION}"`)) return config;
    config.modResults.contents = contents.replace(
      /^android \{/m,
      `android {
    externalNativeBuild {
        cmake {
            version "${CMAKE_VERSION}"
        }
    }`,
    );
    return config;
  });
}; use this first it can be fixed theere

